38	function nativeParent(repo: string, issue: number): number | undefined {
39	  const [owner, name] = repo.split("/", 2);
40	  if (!owner || !name) return undefined;
41	  try {
42	    const data = ghGraphql<{ repository: { issue: { parent: { number: number } | null } } }>(
43	      "query($owner:String!,$repo:String!,$num:Int!){repository(owner:$owner,name:$repo){issue(number:$num){parent{number}}}}",
44	      { owner, repo: name, num: issue },
45	    );
46	    return data.repository.issue.parent?.number;
47	  } catch {
